script:
// AdBlock Plus - InfinityBrowser
const blockedDomains = [
    'doubleclick.net', 'googleadservices.com',
    'googlesyndication.com', 'yandex.ru/ads',
    'adriver.ru', 'adfox.ru'
];

function blockAd(url) {
    for (let domain of blockedDomains) {
        if (url.includes(domain)) {
            return true;
        }
    }
    return false;
}

// Перехват запросов
window.addEventListener('beforeload', function(e) {
    if (blockAd(e.url)) {
        e.preventDefault();
    }
}, true);

// Dark Reader - InfinityBrowser
function enableDarkMode() {
    const style = document.createElement('style');
    style.textContent = `
        html { filter: invert(1) hue-rotate(180deg) brightness(0.9); }
        img, video, iframe { filter: invert(1) hue-rotate(180deg) brightness(0.85); }
    `;
    document.head.appendChild(style);
}

// Включаем темный режим
enableDarkMode();

